INSERT INTO tt_stages(idx,name,story,mob_name,mob_hp,mob_atk,mob_exp,mob_gold,mob_count,boss_name,boss_hp,boss_atk,boss_exp,boss_gold,bg,unlock_level) VALUES
(1,'Vương Bàn Sơn Đảo','Thiên Ưng Giáo mở đại hội Dương Đao Lập Uy, khoe Đồ Long Đao trước quần hùng. Kim Mao Sư Vương Tạ Tốn một mình xông lên đảo đoạt bảo đao.','Đệ Tử Thiên Ưng',117,16,16,7,27,'Bạch Quy Thọ',2340,23,240,126,'#1d3a5f',1),
(2,'Băng Hỏa Đảo','Trôi dạt tới hòn đảo nơi băng giá và núi lửa cùng tồn tại. Cơn cuồng bệnh trong lòng Tạ Tốn trỗi dậy thành Tâm Ma.','Ảo Ảnh Cuồng Ma',207,25,22,10,28,'Tâm Ma Cuồng Sư',4140,36,330,180,'#bfe3f0',4),
(3,'Quang Minh Đỉnh','Lục đại môn phái vây công tổng đàn Minh Giáo. Tạ Tốn là Hộ Giáo Pháp Vương, không thể khoanh tay đứng nhìn.','Đệ Tử Côn Lôn',326,37,30,13,29,'Hà Thái Xung',6520,54,450,234,'#3a1d1d',8),
(4,'Nga Mi Kim Đỉnh','Nga Mi phái truy sát giáo chúng Minh Giáo. Diệt Tuyệt Sư Thái tay cầm Ỷ Thiên Kiếm, kiếm khí lạnh thấu xương.','Nữ Đệ Tử Nga Mi',446,48,38,17,30,'Diệt Tuyệt Sư Thái',8920,70,570,306,'#d9c48a',12),
(5,'Võ Đang Sơn','Triệu Mẫn sai cao thủ Nhữ Dương Vương Phủ đánh úp Võ Đang. Trương Tam Phong bị thương, Võ Đang nguy cấp.','Võ Sĩ Vương Phủ',566,60,46,20,31,'A Nhị',11320,87,690,360,'#2b4a2b',16),
(6,'Vạn An Tự Đại Đô','Cao thủ lục đại phái bị trúng Thập Hương Nhuyễn Cân Tán, giam trên tháp Vạn An Tự. Huyền Minh Nhị Lão canh giữ.','Phiên Tăng Tây Vực',685,72,54,24,32,'Huyền Minh Nhị Lão',13700,104,810,432,'#444444',20),
(7,'Linh Xà Đảo','Tam Sứ Ba Tư Minh Giáo vượt biển tới đòi bắt Đại Ỷ Ti về tổng giáo. Tạ Tốn mù hai mắt vẫn đứng ra cản đường.','Giáo Đồ Ba Tư',835,87,64,28,33,'Diệu Phong Sứ',16700,126,960,504,'#0e4a4a',25),
(8,'Đồ Sư Anh Hùng Hội','Thiếu Lâm mở Đồ Sư Đại Hội, lấy Tạ Tốn làm mồi nhử quần hùng tranh đoạt Đồ Long Đao.','Cao Thủ Quần Hùng',984,102,74,33,34,'Tống Thanh Thư',19680,148,1110,594,'#5a1d5a',30),
(9,'Kim Cang Phục Ma Khuyên','Tam Độ thần tăng Thiếu Lâm ngồi trên ba gốc tùng, dùng Kim Cang Phục Ma Khuyên giam giữ Tạ Tốn dưới hầm đá.','Võ Tăng La Hán',1134,117,84,38,35,'Độ Ách Thần Tăng',22680,170,1260,684,'#6b5a2a',35),
(10,'Quyết Chiến Thành Côn','Thành Côn - kẻ giết cả nhà Tạ Tốn, nay đội lốt Viên Chân hòa thượng. Mối huyết hải thâm thù phải được trả!','Hắc Y Sát Thủ',1283,132,94,42,36,'Thành Côn - Viên Chân',25660,191,1410,756,'#0a0a0a',40),
(11,'Hồ Điệp Cốc','Hồ Điệp Cốc của Điệp Cốc Y Tiên Hồ Thanh Ngưu, nay bị Kim Hoa Bà Bà bao vây truy sát.','Môn Hạ Kim Hoa',1373,141,100,45,37,'Kim Hoa Bà Bà',27460,204,1500,810,'#b07ad0',43),
(12,'Lục Liễu Sơn Trang','Sơn trang của Triệu Mẫn ẩn giữa rừng liễu, cơ quan trùng trùng, cao thủ Vương Phủ canh giữ.','Vệ Sĩ Mông Cổ',1462,149,106,47,38,'Hạc Bút Ông',29240,216,1590,846,'#6a9a7a',46),
(13,'Côn Luân Tam Thánh Phong','Đỉnh tuyết Côn Luân, nơi Côn Luân Tam Thánh Hà Túc Đạo từng đàn cầm luận kiếm.','Kiếm Đồng Côn Luân',1552,158,112,50,39,'Hà Túc Đạo',31040,229,1680,900,'#a8d8f0',49),
(14,'Hoa Sơn Tuyệt Đỉnh','Vách đá Hoa Sơn dựng đứng, kiếm khí ngút trời. Tiên Vu Thông âm mưu đoạt ngôi chưởng môn.','Đệ Tử Hoa Sơn',1642,167,118,53,40,'Tiên Vu Thông',32840,242,1770,954,'#c89a7a',52),
(15,'Không Động Ngũ Lão Phong','Năm ngọn núi của Không Động phái, nơi Thất Thương Quyền được truyền dạy.','Đệ Tử Không Động',1732,176,124,56,41,'Đường Văn Lượng',34640,255,1860,1008,'#8a8aa0',55),
(16,'Cái Bang Tổng Đà','Quân Sơn Cái Bang tổng đà, Trần Hữu Lượng cấu kết Thành Côn mưu đồ bá nghiệp.','Bang Chúng Phản Loạn',1821,185,130,58,42,'Trần Hữu Lượng',36420,268,1950,1044,'#5a4a6a',58),
(17,'Quang Minh Mật Đạo','Đường hầm bí mật dưới Quang Minh Đỉnh, nơi Dương Đỉnh Thiên tẩu hỏa nhập ma năm xưa.','Hắc Y Nhân',1911,194,136,61,43,'Thanh Dực Bức Vương',38220,281,2040,1098,'#6a2a2a',61),
(18,'Ba Tư Thánh Hỏa Đàn','Thánh đàn Minh Giáo Ba Tư trên biển, lửa thánh cháy không bao giờ tắt.','Thánh Hỏa Vệ Binh',2001,203,142,64,44,'Lưu Vân Sứ',40020,294,2130,1152,'#e0904a',64),
(19,'Thiếu Thất Tàng Kinh Các','Tàng Kinh Các Thiếu Lâm - nơi cất giữ bí kíp thất truyền, Tam Độ canh giữ ngày đêm.','Võ Tăng Tàng Kinh',2090,212,148,66,45,'Độ Kiếp Thần Tăng',41800,307,2220,1188,'#c8a86a',67),
(20,'Võ Lâm Chí Tôn Đài','Đài Chí Tôn trên đỉnh Tung Sơn - ai thắng sẽ là Võ Lâm Chí Tôn, hiệu lệnh thiên hạ.','Cao Thủ Thiên Hạ',2180,221,154,69,46,'Chu Chỉ Nhược',43600,320,2310,1242,'#2a1a4a',70),
(21,'Long Môn Tiêu Cục','Long Môn Tiêu Cục nhận áp tiêu đưa Du Đại Nham về Võ Đang, nhưng cả tiêu cục bị thảm sát trong một đêm. Kim Cang Môn đứng sau tất cả.','Đệ Tử Kim Cang Môn',2270,230,160,72,47,'Kim Cang Môn Chủ',45400,334,2400,1296,'#1a1530',73),
(22,'Hồng Mai Sơn Trang','Sơn trang của Chu Cửu Chân, hoa mai đỏ rợp trời, đàn chó dữ cùng gia đinh canh giữ ngày đêm.','Gia Đinh Chu Gia',2360,239,166,74,48,'Chu Trường Linh',47200,347,2490,1332,'#d87a8a',76),
(23,'Côn Luân Viên Hầu Cốc','Thung lũng biệt lập dưới vách Côn Luân, nơi bạch viên giấu Cửu Dương Chân Kinh trong bụng suốt trăm năm.','Hầu Tử Sơn Cốc',2449,248,172,77,49,'Bạch Viên Thần Hầu',48980,360,2580,1386,'#6ab07a',79),
(24,'Hải Sa Bến Cảng','Bến cảng muối của Hải Sa Phái - bọn chúng rải muối độc hại người giang hồ, cướp thuyền buôn trên biển.','Đệ Tử Hải Sa',2539,256,178,80,50,'Nguyên Quảng Ba',50780,371,2670,1440,'#4a90c0',82),
(25,'Tây Vực Đại Mạc','Sa mạc mênh mông trên đường tới Quang Minh Đỉnh, lục đại phái phục kích giáo chúng Minh Giáo giữa bão cát.','Kỵ Binh Sa Mạc',2629,265,184,82,51,'Tây Hoa Tử',52580,384,2760,1476,'#e8b060',85),
(26,'Nhữ Dương Vương Phủ','Vương phủ Mông Cổ canh phòng nghiêm ngặt, Triệu Mẫn giam giữ cao thủ giang hồ trong ngục tối.','Thị Vệ Vương Phủ',2718,274,190,85,52,'Nhữ Dương Vương',54360,397,2850,1530,'#20183a',88),
(27,'Đại Đô Hoàng Thành','Kinh thành Đại Đô của triều Nguyên, cấm vệ quân Mông Cổ trùng trùng điệp điệp bảo vệ hoàng cung.','Cấm Vệ Quân',2808,283,196,88,53,'Vương Bảo Bảo',56160,410,2940,1584,'#8a5a3a',91),
(28,'Ỷ Thiên Kiếm Trủng','Hang động bí ẩn nơi Quách Tương năm xưa chôn giấu bí mật của Ỷ Thiên Kiếm và Đồ Long Đao.','Kiếm Linh Cổ Trủng',2898,292,202,91,54,'Kiếm Trủng Thủ Hộ',57960,423,3030,1638,'#20283a',94),
(29,'Thiên Sơn Tuyết Lĩnh','Đỉnh Thiên Sơn quanh năm tuyết phủ, Tuyết Lĩnh Song Xú chiếm núi xưng vương, chặn đường người qua lại.','Tuyết Sơn Đao Khách',2957,298,206,92,55,'Băng Phách Ma Quân',59140,432,3090,1656,'#b8e0f8',96),
(30,'Thánh Hỏa Tuyệt Đỉnh','Trận quyết chiến cuối cùng trên Thánh Hỏa Đỉnh - nơi tâm ma của cả võ lâm tụ lại thành Hỗn Nguyên Ma Tôn.','Ma Giáo Tử Sĩ',3017,304,210,94,56,'Hỗn Nguyên Ma Tôn',60340,441,3150,1692,'#3a0a1a',98);
